const payload = $input.first().json.body;
if (!payload.brand_id || !payload.post_id) throw new Error('brand_id and post_id are required');
if (!payload.revision_reason || payload.revision_reason.trim().length < 5) throw new Error('revision_reason must be at least 5 characters');
return {
  brand_id: payload.brand_id,
  post_id: payload.post_id,
  revision_reason: payload.revision_reason,
  revision_type: payload.revision_type || 'caption',
  special_instructions: payload.special_instructions || '',
  target: payload.target === 'admin' ? 'admin' : 'user',
  image_model: payload.image_model || 'auto',
  created_by: payload.created_by || null,
  request_id: payload.request_id || null,
  prompt_override: payload.prompt_override || null,
  requested_at: new Date().toISOString(),
  flow_id: 'N8N-B03'
};

const post = $input.first().json;
const target = $('Validate Revision Request1').first().json.target;
const revisionCount = post.revision_count || 0;
if (target !== 'admin' && revisionCount >= 3) throw new Error(`MAX_REVISIONS_EXCEEDED: Post revised ${revisionCount} times. Max 3.`);
return { ...post, revision_count: revisionCount, new_revision_number: revisionCount + 1, can_revise: true };

const crypto = require('crypto');
const validate = $('Validate Revision Request1').first().json;
const checkCount = $('Check Revision Count1').first().json;
const bodyObj = {
  flow_id: 'N8N-B03',
  brand_id: validate.brand_id,
  payload: {
    request_type: 'revision',
    trigger_payload: {
      post_id: validate.post_id,
      revision_reason: validate.revision_reason,
      revision_number: checkCount.new_revision_number,
      max_revisions: 3,
      original_caption: checkCount.caption_ar,
      original_score: checkCount.confidence_score || 75
    }
  }
};
const bodyStr = JSON.stringify(bodyObj);
const secret = 'test-webhook-secret-123';
const ts = new Date().toISOString();
const rid = crypto.randomUUID();
const sig = crypto.createHmac('sha256', secret).update(bodyStr).digest('hex');
return { signedBody: bodyStr, sig, rid, ts };

const crypto = require('crypto');
const validate = $('Validate Revision Request1').first().json;
const ceoResult = $('HTTP: CEO Scope Revision1').first().json;
const brand = $('Supabase: Fetch Brand Profile1').first().json;
const checkCount = $('Check Revision Count1').first().json;
