const crypto = require('crypto');
const validate = $('Validate Revision Request1').first().json;
const checkCount = $('Check Revision Count1').first().json;
const cooResult = $('HTTP: COO Re-Brief1').first().json;

const captionContext = cooResult.result?.caption_context || '';
if (!captionContext) throw new Error('COO caption_context missing — cannot call DeepSeek');

// DeepSeek contract: post_count MUST equal schedule_dates.length, and the model
// returns posts=[] (the "0 posts" 502) when schedule_dates is empty. Build one
// schedule entry from the post's posting_time — same shape as N8N-A02's
// Prepare DeepSeek node. Falls back to now() if posting_time is missing/invalid.
let rawPostingTime = checkCount.posting_time || '';
let dateObj = new Date(rawPostingTime);
if (isNaN(dateObj.getTime())) { dateObj = new Date(); rawPostingTime = dateObj.toISOString(); }
const scheduleDate = dateObj.toISOString().slice(0, 10);
const month = scheduleDate.slice(0, 7);
const hourMatch = String(rawPostingTime).match(/T(\d{2}):/);
const scheduleHour = hourMatch ? parseInt(hourMatch[1], 10) : dateObj.getUTCHours();
const schedule_dates = [{ date: scheduleDate, posting_time: rawPostingTime, hour: scheduleHour }];

const bodyObj = {
  flow_id: 'N8N-B03',
  brand_id: validate.brand_id,
  payload: {
    month: month,
    caption_context: captionContext,
    post_count: 1,
    schedule_dates: schedule_dates,
    start_date: scheduleDate,
    intended_format: (checkCount.media_type === 'video') ? 'video' : 'image',
    watermark_required: cooResult.result?.watermark_flag || false
  }
};
const bodyStr = JSON.stringify(bodyObj);
const secret = 'test-webhook-secret-123';
const ts = new Date().toISOString();
const rid = crypto.randomUUID();
const sig = crypto.createHmac('sha256', secret).update(bodyStr).digest('hex');
return { signedBody: bodyStr, sig, rid, ts };

