const crypto = require('crypto');
const validate = $('Validate Revision Request1').first().json;
const ccoResult = $('HTTP: CCO Revised QC1').first().json;
const bodyObj = {
  flow_id: 'N8N-B03',
  brand_id: validate.brand_id,
  payload: {
    request_type: 'revision',
