// Builds the flat input shape that N8N-V01's executeWorkflowTrigger expects.
// V01 reads top-level fields and signs the /api/image/generate call itself.
//
// To preserve the original user-typed brief across regenerations we:
//   1. Load the on_demand_requests row (if this post originated from A02).
//   2. Build prompt_en from hero_concept + style_descriptor when available.
//   3. Honor the user's original chain_id (CEO's selected_chain at A02 time).
//   4. Fall back to DeepSeek's revised visual_brief_en for non-on-demand posts.
const validate = $('Validate Revision Request1').first().json;
const revisedCaption = $('HTTP: DeepSeek Revised Caption1').first().json.result.posts[0];
const brandData = $('Supabase: Fetch Brand Profile1').first().json;
const originalPost = $('Check Revision Count1').first().json;

// Load the on_demand_requests row (may be absent for A01 monthly-batch posts).
let onDemandReq = null;
try {
  const items = $('Supabase: Fetch OnDemand Request1').all();
  if (items.length > 0 && items[0].json && items[0].json.request_id) {
    onDemandReq = items[0].json;
  }
} catch (e) {
  onDemandReq = null;
}

// Capture chain_id selected by CEO during initial classification (if any).
let chainId = null;
try {
  const ceoResult = $('HTTP: CEO Scope Revision1').first().json;
  chainId = (ceoResult && ceoResult.result && ceoResult.result.decision && ceoResult.result.decision.selected_chain) || null;
} catch (e) {
  chainId = null;
}

// Hard Rule #3 guard: NO Arabic in prompt_en.
const ARABIC_RE = /[\u0600-\u06FF]/;

// Prompt source priority:
//   1. on_demand_requests.hero_concept + style_descriptor (original user brief)
//   2. DeepSeek's revised visual_brief_en (when no on-demand row exists)
//   3. Generic brand fallback
let promptEn = '';
if (onDemandReq && onDemandReq.hero_concept) {
  const parts = [onDemandReq.hero_concept];
  if (onDemandReq.style_descriptor) parts.push(onDemandReq.style_descriptor);
  promptEn = parts.join('. ').trim();
}
if (!promptEn) {
  promptEn = (revisedCaption.visual_brief_en || '').trim();
}
if (!promptEn || ARABIC_RE.test(promptEn)) {
  promptEn = `${brandData.brand_name_en || 'brand'} product photo, clean background, natural lighting`;
}

// Prefer user-typed scene palette; fall back to brand primary color.
const primaryColorHex = (onDemandReq && Array.isArray(onDemandReq.color_palette) && onDemandReq.color_palette.length > 0)
  ? onDemandReq.color_palette[0]
  : (brandData.primary_color_hex || '');

// Validate against /api/image/generate enum constraints; safe fallbacks otherwise.
const validObjectives = ['awareness', 'engagement', 'conversion', 'cultural', 'trust'];
const objective = (onDemandReq && validObjectives.includes(onDemandReq.objective))
  ? onDemandReq.objective
  : (revisedCaption.content_type === 'offer' ? 'conversion' : 'awareness');

const validChannels = ['Instagram', 'Snapchat', 'TikTok', 'Twitter'];
const channel = (onDemandReq && validChannels.includes(onDemandReq.platform))
  ? onDemandReq.platform
  : (brandData.primary_channel || 'Instagram');


// Admin/user prompt_override (English-only, Hard Rule #3) takes precedence.
const override = validate.prompt_override || null;
if (override && override.hero_concept) {
  const ovParts = [override.hero_concept];
  if (override.style_descriptor) ovParts.push(override.style_descriptor);
  const ov = ovParts.join('. ').trim();
  if (ov && !ARABIC_RE.test(ov)) promptEn = ov;
}

return {
  brand_id: validate.brand_id,
  post_id: originalPost.post_id,
  prompt_en: promptEn,
  brand_name_ar: brandData.brand_name_ar || '',
  headline_ar: (revisedCaption.caption_ar || '').slice(0, 50),
  dialect: brandData.arabic_dialect || 'MSA_accessible',
  channel: channel,
  objective: objective,
  confidence_flag: 'clean',
  primary_color_hex: primaryColorHex,
  revision_count: originalPost.new_revision_number,
  chain_id: chainId,
  image_model: validate.image_model || 'auto'
};

const visualResult = $input.first().json;
const revisedCaption = $('HTTP: DeepSeek Revised Caption1').first().json.result.posts[0];
const gateDecision = $('HTTP: CEO Revision Gate1').first().json.result.decision;
const ccoEval = $('HTTP: CCO Revised QC1').first().json.result[0];
const originalPost = $('Check Revision Count1').first().json;
const revision = $('Validate Revision Request1').first().json;
const confidenceMode = gateDecision.confidence_mode || 'Standard';
const confidenceScore = ccoEval?.score ?? 75;
const watermarkRequired = confidenceMode !== 'Standard';

const newStorageUrl =
  visualResult.result?.storage_url ||
  visualResult.storage_url ||
  '';
if (!newStorageUrl) {
  throw new Error('Visual generation returned empty storage_url — aborting post update');
}
const newCleanStorageUrl =
  visualResult.result?.clean_storage_url ||
  visualResult.clean_storage_url ||
  null;

const oldStorageUrl = originalPost.storage_url || null;
const oldCleanStorageUrl = originalPost.clean_storage_url || null;

// Always write a non-null clean_storage_url so the Supabase node never skips
// the field. Fall back to the previous clean URL if V01 returned null.
const finalCleanStorageUrl = newCleanStorageUrl || oldCleanStorageUrl;

// Defensive parse: Supabase JSONB may come back as a JSON string instead of
// a parsed array depending on how n8n reads it. Spreading a string produces
// individual characters and corrupts the history.
let existingHistory = [];
const raw = originalPost.revision_history;
if (Array.isArray(raw)) {
  existingHistory = raw;
} else if (typeof raw === 'string' && raw.length > 0) {
  try {
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) existingHistory = parsed;
  } catch { }
}

return {
  brand_id: revision.brand_id,
  post_id: originalPost.post_id,
  caption_ar: revisedCaption.caption_ar,
  storage_url: newStorageUrl,
  clean_storage_url: finalCleanStorageUrl,
  content_type: revisedCaption.content_type || originalPost.content_type,
  hashtags: revisedCaption.hashtags || originalPost.hashtags || [],
  confidence_score: confidenceScore,
  watermark: watermarkRequired,
  status: 'approved',
  revision_count: originalPost.new_revision_number,
  revision_history: [
    ...existingHistory,
    {
      revision_number: originalPost.new_revision_number,
      reason: revision.revision_reason,
      old_caption: originalPost.caption_ar,
      new_caption: revisedCaption.caption_ar,
      old_image_url: oldStorageUrl,
      old_clean_image_url: oldCleanStorageUrl,
      new_image_url: newStorageUrl,
      new_clean_image_url: newCleanStorageUrl,
      confidence_score: confidenceScore,
      confidence_mode: confidenceMode,
      revised_at: new Date().toISOString()
    }
  ],
  updated_at: new Date().toISOString()
};

const revision = $('Validate Revision Request1').first().json;
const ceoResponse = $input.first().json;
return {
  brand_id: revision.brand_id,
  post_id: revision.post_id,
  rejection_reason: ceoResponse.result?.decision?.human_gate_reasons?.join(', ') || 'CEO human gate required — manual review needed',
  flow_id: 'N8N-B03',
  status: 'rejected',
  created_at: new Date().toISOString()
};

const revisedCaption = $('HTTP: DeepSeek Revised Caption1').first().json.result.posts[0];
const gateDecision = $('HTTP: CEO Revision Gate1').first().json.result.decision;
const revision = $('Validate Revision Request1').first().json;
const holdReason = 'Revision gate required human review: ' + ((gateDecision.human_gate_reasons || []).join(', ') || 'confidence gate triggered');
return [{
  json: {
    brand_id:       revision.brand_id,
    post_id:        revision.post_id,
    caption_ar:     revisedCaption.caption_ar,
    cco_score:      50,
    flags:          { flow_id: 'N8N-B03', route: 'HOLD' },
    trigger_reason: holdReason,
    status:         'pending'
  }
}];

const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const e = $json;

let brand_id = null;
try { brand_id = $('Validate Revision Request1').first().json.brand_id ?? null; } catch (_) {}

const makeUUID = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});

const body = JSON.stringify({
  anomaly_id:   makeUUID(),
  anomaly_type: 'revision_request_failed',
  severity:     'error',
  source_flow:  'N8N-B03',
  brand_id,
  message:      e.execution?.error?.message || 'B03 revision request flow failed',
  details: {
    failed_node:  e.execution?.lastNodeExecuted ?? null,
    error_name:   e.execution?.error?.name      ?? null,
    execution_id: e.execution?.id               ?? null,
  },
  timestamp: new Date().toISOString(),
});

const sig = crypto.createHmac('sha256', SECRET).update(body).digest('hex');
return {
  _body: body,
  _headers: {
    'content-type':     'application/json',
    'x-n8n-signature':  sig,
    'x-n8n-request-id': `${$execution.id}-err-b03`,
    'x-n8n-timestamp':  new Date().toISOString(),
  },
};

const update = $('Prepare Post Update1').first().json;
const validate = $('Validate Revision Request1').first().json;
const post = $('Check Revision Count1').first().json;

// Next admin draft version for this post (independent of user revision_count).
let maxVersion = 0;
try {
  for (const it of $('Supabase: Fetch Admin Regen Count1').all()) {
    const v = it.json && it.json.version ? Number(it.json.version) : 0;
    if (v > maxVersion) maxVersion = v;
  }
} catch (e) { maxVersion = 0; }

return {
  post_id: update.post_id,
  request_id: validate.request_id,
  brand_id: validate.brand_id,
  version: maxVersion + 1,
  media_type: post.media_type || 'image',
  storage_url: update.storage_url,
  clean_storage_url: update.clean_storage_url,
  caption_ar: update.caption_ar,
  hashtags: update.hashtags || [],
  confidence_score: update.confidence_score,
  watermark: update.watermark,
  prompt_override: validate.prompt_override || null,
  image_model: validate.image_model || 'auto',
  status: 'draft',
  created_by: validate.created_by
};
